package com.casystem.onboarding.config;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;@RestControllerAdvice public class ApiExceptionHandler{@ExceptionHandler(SecurityException.class)ResponseEntity<?> security(SecurityException e){return ResponseEntity.status(401).body(Map.of("error",e.getMessage()));}@ExceptionHandler(Exception.class)ResponseEntity<?> general(Exception e){return ResponseEntity.status(400).body(Map.of("error",e.getMessage()==null?"Error al procesar la solicitud":e.getMessage()));}}